/**
 * Object to represent user credentials.
 */
export interface Credentials {
    name: string;
    pass: string;
}
/**
 * Parse basic auth to object.
 *
 * @param {string} string
 * @return {object}
 * @public
 */
export declare function parse(string: string): Credentials | undefined;
/**
 * Format Basic Authorization Header
 *
 * @param {Credentials} credentials
 * @return {string}
 * @public
 */
export declare function format(credentials: Credentials): string;
